package com.community.dashboard.controller;

import com.community.dashboard.entity.UserPreset;
import com.community.dashboard.repository.UserPresetRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/users/presets")
public class UserPresetController {

    private final UserPresetRepository presetRepository;

    public UserPresetController(UserPresetRepository presetRepository) {
        this.presetRepository = presetRepository;
    }

    @PutMapping("/{presetId}")
    public ResponseEntity<String> updatePresetDetails(
            @PathVariable Long presetId,
            @RequestBody UserPreset updatedData,
            Authentication authentication) {
        UserPreset preset = presetRepository.findByIdAndUserUsername(presetId, authentication.getName())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Preset not found or not owned by caller"));
        preset.setThemeColor(updatedData.getThemeColor());
        preset.setAvatarBorder(updatedData.getAvatarBorder());
        presetRepository.save(preset);
        return ResponseEntity.ok("Preset updated");
    }
}
